CREATE TABLE companion_bond (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,user_id BIGINT,character_code VARCHAR(20),revision BIGINT DEFAULT 0,profile VARCHAR(1200) DEFAULT '',profile_revision BIGINT DEFAULT 0,time_zone VARCHAR(80) DEFAULT 'Asia/Taipei',UNIQUE(user_id,character_code));
CREATE TABLE companion_session (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,user_id BIGINT,character_code VARCHAR(20),title VARCHAR(80) DEFAULT '',summary CLOB DEFAULT '',summary_until_message_id BIGINT DEFAULT 0,window_start_message_id BIGINT DEFAULT 0,message_count INT DEFAULT 0,last_message_time TIMESTAMP,context_snapshot CLOB,snapshot_time TIMESTAMP,unread BOOLEAN DEFAULT FALSE);
CREATE TABLE companion_message (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,session_id BIGINT,role VARCHAR(20),content CLOB,bubbles CLOB,image_ids CLOB,sources CLOB,safety_label VARCHAR(30),completed BOOLEAN DEFAULT FALSE,client_message_id VARCHAR(80),turn_id BIGINT,turn_state VARCHAR(20),kind VARCHAR(20) DEFAULT 'TEXT',sticker VARCHAR(60),prompt_version VARCHAR(180),model VARCHAR(120),memory_ids CLOB,metrics CLOB,request_revision BIGINT DEFAULT 0,time_zone VARCHAR(80) DEFAULT 'Asia/Taipei',UNIQUE(session_id,client_message_id));
CREATE TABLE companion_memory (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,user_id BIGINT,character_code VARCHAR(20),content VARCHAR(240),content_hash VARCHAR(64),source_message_id BIGINT,source_session_id BIGINT,last_used_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,kind VARCHAR(20) DEFAULT 'LIFE',keywords CLOB,importance INT DEFAULT 5,embedding CLOB,embedding_version VARCHAR(30),pinned BOOLEAN DEFAULT FALSE,valid_from TIMESTAMP DEFAULT CURRENT_TIMESTAMP,invalid_at TIMESTAMP,superseded_by BIGINT,active_content_hash VARCHAR(64) GENERATED ALWAYS AS (CASE WHEN delete_state=0 AND invalid_at IS NULL THEN content_hash ELSE NULL END),UNIQUE(user_id,character_code,active_content_hash));
CREATE TABLE companion_card (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,character_code VARCHAR(20),version VARCHAR(80),content CLOB,active BOOLEAN DEFAULT FALSE,UNIQUE(character_code,version));
CREATE TABLE companion_line (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,character_code VARCHAR(20),scene VARCHAR(30),dialogue CLOB,version VARCHAR(80),enabled BOOLEAN DEFAULT TRUE);
CREATE TABLE companion_outbox (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,event_id VARCHAR(80),event_type VARCHAR(100),payload CLOB,status VARCHAR(20) DEFAULT 'PENDING',retry_count INT DEFAULT 0,UNIQUE(event_id));
CREATE TABLE companion_processed (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,event_id VARCHAR(80) UNIQUE);
CREATE TABLE companion_safety_event (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,user_id BIGINT,character_code VARCHAR(20),message_id BIGINT,kind VARCHAR(30));
CREATE TABLE companion_image (id BIGINT AUTO_INCREMENT PRIMARY KEY,create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP,delete_state INT DEFAULT 0,user_id BIGINT,file_path VARCHAR(200) UNIQUE);
